  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `game_player_game_id_foreign` (`game_id`),
  KEY `game_player_player_id_foreign` (`player_id`),
