DROP TABLE IF EXISTS `games`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `games` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `tournament_id` bigint unsigned DEFAULT NULL,
  `is_playoff` tinyint(1) NOT NULL DEFAULT '0',
  `local_team_id` bigint unsigned DEFAULT NULL,
  `away_team_id` bigint unsigned DEFAULT NULL,
  `court_id` bigint unsigned DEFAULT NULL,
  `date_time` datetime DEFAULT NULL,
  `status` enum('pending','playing','finished') COLLATE utf8mb4_unicode_ci NOT NULL,
  `group_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `settings` json DEFAULT NULL,
  `category_group` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `local_team_score` int DEFAULT NULL,
  `away_team_score` int DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `period` int NOT NULL DEFAULT '1',
  `seconds_remaining` int DEFAULT NULL,
  `timer_status` enum('stopped','running','finished') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'stopped',
  `referee_id` bigint unsigned DEFAULT NULL,
  `client_id` bigint unsigned DEFAULT NULL,
  `next_game_winners_id` bigint unsigned DEFAULT NULL,
  `next_game_losers_id` bigint unsigned DEFAULT NULL,
  `round_number` int DEFAULT '1',
  `bracket_type` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `games_tournament_id_foreign` (`tournament_id`),
  KEY `games_local_team_id_foreign` (`local_team_id`),
  KEY `games_away_team_id_foreign` (`away_team_id`),
  KEY `games_court_id_foreign` (`court_id`),
  KEY `games_referee_id_foreign` (`referee_id`),
  KEY `games_next_game_winners_id_foreign` (`next_game_winners_id`),
  KEY `games_next_game_losers_id_foreign` (`next_game_losers_id`),
  CONSTRAINT `games_away_team_id_foreign` FOREIGN KEY (`away_team_id`) REFERENCES `teams` (`id`) ON DELETE CASCADE,
  CONSTRAINT `games_court_id_foreign` FOREIGN KEY (`court_id`) REFERENCES `courts` (`id`) ON DELETE CASCADE,
  CONSTRAINT `games_local_team_id_foreign` FOREIGN KEY (`local_team_id`) REFERENCES `teams` (`id`) ON DELETE CASCADE,
  CONSTRAINT `games_next_game_losers_id_foreign` FOREIGN KEY (`next_game_losers_id`) REFERENCES `games` (`id`) ON DELETE SET NULL,
  CONSTRAINT `games_next_game_winners_id_foreign` FOREIGN KEY (`next_game_winners_id`) REFERENCES `games` (`id`) ON DELETE SET NULL,
  CONSTRAINT `games_referee_id_foreign` FOREIGN KEY (`referee_id`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `games_tournament_id_foreign` FOREIGN KEY (`tournament_id`) REFERENCES `tournaments` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=7464 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
