INSERT INTO `tournaments` VALUES (5,'Libre',NULL,NULL,'2026-07-19','2026-12-31',NULL,'pending',0,'Varonil','2026-06-05 17:05:37','2026-07-23 15:28:34',NULL,'A',1),(6,'Oceania',NULL,NULL,'2026-07-19','2026-07-26','Deportivo Oceania','active',1,'Mixto','2026-07-14 22:22:58','2026-07-19 19:21:35',NULL,'Libre',1),(7,'Caracoles 3x3','tournaments/RnmRTOnv6hnecu0SS3OTPdxV5ZlnyG58SxIqUNkd.png',NULL,'2026-07-26','2026-08-02','Deportivo Caracoles','active',1,'Mixto','2026-07-14 22:23:24','2026-07-26 19:45:29','<ol><li data-list=\"ordered\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Equipos y jugadores</strong> Cada equipo estará compuesto por 4 jugadores (3 jugadores en la cancha y 1 sustituto). No están permitidos los entrenadores</li><li data-list=\"ordered\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Inicio del partido</strong> Primera posesión del balón será sorteada. El equipo que gana el sorteo podrá escoger la primera posesión al inicio del partido o al inicio de una posible prórroga. Obligatorio 3 jugadores en cancha para empezar.</li><li data-list=\"ordered\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Puntuación</strong> 1 punto dentro del arco y tiros libres. 2 puntos fuera del arco</li><li data-list=\"ordered\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Duración del partidos </strong>1<strong> </strong>Periodo<strong> </strong>de 10 minutos. Límite de anotación: <strong>knock out</strong> 21 puntos (solo para el tiempo regular). Desempates: sin tiempo. El primer equipo en anotar 2 puntos en el periodo extra ganará el encuentro</li><li data-list=\"ordered\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Tiempos muertos</strong> 1 para cada equipo. 30 segundos de duración. Cualquier jugador puede pedir el tiempo muerto en una situación de balón muerto.</li><li data-list=\"ordered\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Tiros libres</strong> Después de una falta de tiro 1 tiro libre. 2 tiros libres si la falta se comete detrás del arco.</li><li data-list=\"ordered\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Límite de faltas de equipo</strong> 6 faltas de equipo. Los jugadores no acumulan faltas, sólo el equipo</li><li data-list=\"ordered\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Penalización para las faltas de equipo 7ª, 8ª y 9ª</strong> 2 tiros libres en todos los casos. (No existe el concepto de tiro libre adicional durante una falta en acción de tiro y canasta convertida.)</li><li data-list=\"ordered\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Penalización para las faltas de equipo 10ª y posteriores</strong> 2 tiros libres y posesión de balón en todos los casos. (No existe el concepto de tiro libre adicional durante una falta en acción de tiro y canasta convertida.)</li><li data-list=\"ordered\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Posesión después de una canasta convertida</strong> Posesión para el equipo defensor justo debajo del aro. El balón será botado hasta o pasado a un jugador detrás del arco. Se considerará que un jugador está “detrás del arco” si ninguno de sus pies está encima o dentro del arco. No se le permite al equipo defensor jugar el balón dentro del área del semicírculo de no carga debajo del aro.</li></ol><p><br></p>','Libre',1),(8,'Libre Femenil',NULL,NULL,'2026-07-19','2026-12-30',NULL,'pending',0,'Femenil','2026-07-14 22:38:57','2026-07-27 00:34:01','<p>Q</p>','A',1);
/*!40000 ALTER TABLE `tournaments` ENABLE KEYS */;
UNLOCK TABLES;

